import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"参考","description":"","frontmatter":{},"headers":[],"relativePath":"reference.md","filePath":"reference.md","lastUpdated":1790910996000}`),a={name:`reference.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to “参考”">​</a></h1><p>本页汇总设计模式相关的经典书籍、在线资源与站内文档索引，便于进一步查阅。</p><h2 id="经典书籍" tabindex="-1">经典书籍 <a class="header-anchor" href="#经典书籍" aria-label="Permalink to “经典书籍”">​</a></h2><ul><li>《设计模式：可复用面向对象软件的基础》（Design Patterns: Elements of Reusable Object-Oriented Software），Erich Gamma、Richard Helm、Ralph Johnson、John Vlissides（&quot;四人帮&quot;/GoF）。设计模式领域的开山之作，定义了 23 种经典模式及其意图、适用性与结构。</li><li>《Head First 设计模式》（Head First Design Patterns），Eric Freeman 等。以图形化、案例化的方式讲解经典模式，适合入门。</li><li>《面向对象分析与设计》（Object-Oriented Analysis and Design with Applications），Grady Booch 等。讲解面向对象基础与模式在软件生命周期中的应用。</li><li>《企业应用架构模式》（Patterns of Enterprise Application Architecture），Martin Fowler。覆盖企业级应用中的领域逻辑、数据映射、Web 表现层等模式。</li><li>《重构：改善既有代码的设计》（Refactoring: Improving the Design of Existing Code），Martin Fowler。说明如何通过重构手法把代码逐步整理为引入模式的形态。</li><li>《重构与模式》（Refactoring to Patterns），Joshua Kerievsky。给出从常见坏味道到设计模式的演进路径。</li><li>《软件架构师修炼指南》（Pattern-Oriented Software Architecture），Frank Buschmann 等（POSA 系列）。系统化讲解通信、并发、结构等架构层模式。</li><li>《并发模式与企业集成模式》（Enterprise Integration Patterns），Gregor Hohpe、Bobby Woolf。消息、路由、转换等集成与并发相关模式的集合。</li></ul><h2 id="在线资源" tabindex="-1">在线资源 <a class="header-anchor" href="#在线资源" aria-label="Permalink to “在线资源”">​</a></h2><ul><li>Refactoring.Guru：按语言分类的模式教程，含意图、结构、适用场景与示例代码。</li><li>SourceMaking：设计模式与反模式的系统站点，附 UML 图与优缺点说明。</li><li>Wikipedia：Software design pattern / Behavioral pattern 等词条，适合快速核对模式定义。</li><li>dofactory：经典 GoF 模式的模式分类与代码示例。</li><li>Martin Fowler 的个人站点（martinfowler.com）：重构、企业应用架构、演进式架构等文章。</li><li>Java 官方文档 java.util.concurrent 包说明：Future、Semaphore、BlockingQueue 等并发模式的标准库实现。</li></ul><h2 id="站内文档索引" tabindex="-1">站内文档索引 <a class="header-anchor" href="#站内文档索引" aria-label="Permalink to “站内文档索引”">​</a></h2><h3 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to “概览”">​</a></h3><ul><li><a href="/hello-design-patterns/introduction">设计模式概览</a></li></ul><h3 id="创建型模式" tabindex="-1">创建型模式 <a class="header-anchor" href="#创建型模式" aria-label="Permalink to “创建型模式”">​</a></h3><ul><li><a href="/hello-design-patterns/creational/overview">创建型模式导读</a></li><li><a href="/hello-design-patterns/creational/singleton">单例模式</a></li><li><a href="/hello-design-patterns/creational/factory-method">工厂方法模式</a></li><li><a href="/hello-design-patterns/creational/abstract-factory">抽象工厂模式</a></li><li><a href="/hello-design-patterns/creational/builder">建造者模式</a></li><li><a href="/hello-design-patterns/creational/prototype">原型模式</a></li><li><a href="/hello-design-patterns/creational/multiton">多例模式</a></li><li><a href="/hello-design-patterns/creational/object-pool">对象池模式</a></li><li><a href="/hello-design-patterns/creational/service-locator">服务定位器模式</a></li></ul><h3 id="结构型模式" tabindex="-1">结构型模式 <a class="header-anchor" href="#结构型模式" aria-label="Permalink to “结构型模式”">​</a></h3><ul><li><a href="/hello-design-patterns/structural/overview">结构型模式导读</a></li><li><a href="/hello-design-patterns/structural/adapter">适配器模式</a></li><li><a href="/hello-design-patterns/structural/decorator">装饰模式</a></li><li><a href="/hello-design-patterns/structural/proxy">代理模式</a></li><li><a href="/hello-design-patterns/structural/virtual-proxy">虚拟代理模式</a></li><li><a href="/hello-design-patterns/structural/protection-proxy">保护代理模式</a></li><li><a href="/hello-design-patterns/structural/remote-proxy">远程代理模式</a></li><li><a href="/hello-design-patterns/structural/dynamic-proxy">动态代理模式</a></li><li><a href="/hello-design-patterns/structural/smart-pointer">智能指引模式</a></li><li><a href="/hello-design-patterns/structural/facade">外观模式</a></li><li><a href="/hello-design-patterns/structural/bridge">桥接模式</a></li><li><a href="/hello-design-patterns/structural/bidirectional-bridge">双向桥接模式</a></li><li><a href="/hello-design-patterns/structural/composite">组合模式</a></li><li><a href="/hello-design-patterns/structural/flyweight">享元模式</a></li><li><a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a></li></ul><h3 id="行为型模式" tabindex="-1">行为型模式 <a class="header-anchor" href="#行为型模式" aria-label="Permalink to “行为型模式”">​</a></h3><ul><li><a href="/hello-design-patterns/behavioral/overview">行为型模式导读</a></li><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a></li><li><a href="/hello-design-patterns/behavioral/observer">观察者模式</a></li><li><a href="/hello-design-patterns/behavioral/command">命令模式</a></li><li><a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链模式</a></li><li><a href="/hello-design-patterns/behavioral/mediator">中介者模式</a></li><li><a href="/hello-design-patterns/behavioral/iterator">迭代器模式</a></li><li><a href="/hello-design-patterns/behavioral/template-method">模板方法模式</a></li><li><a href="/hello-design-patterns/behavioral/state">状态模式</a></li><li><a href="/hello-design-patterns/behavioral/memento">备忘录模式</a></li><li><a href="/hello-design-patterns/behavioral/snapshot">快照模式</a></li><li><a href="/hello-design-patterns/behavioral/interpreter">解释器模式</a></li><li><a href="/hello-design-patterns/behavioral/visitor">访问者模式</a></li><li><a href="/hello-design-patterns/behavioral/callback">回调模式</a></li><li><a href="/hello-design-patterns/behavioral/dsl">领域特定语言（DSL）</a></li></ul><h3 id="并发模式" tabindex="-1">并发模式 <a class="header-anchor" href="#并发模式" aria-label="Permalink to “并发模式”">​</a></h3><ul><li><a href="/hello-design-patterns/concurrency/overview">并发模式导读</a></li><li><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者模式</a></li><li><a href="/hello-design-patterns/concurrency/semaphore">信号量模式</a></li><li><a href="/hello-design-patterns/concurrency/future">Future 模式</a></li><li><a href="/hello-design-patterns/concurrency/active-object">主动对象模式</a></li><li><a href="/hello-design-patterns/concurrency/double-checked-locking">双重检查锁定模式</a></li><li><a href="/hello-design-patterns/concurrency/event-loop">事件循环模式</a></li><li><a href="/hello-design-patterns/concurrency/reactor">反应器模式</a></li><li><a href="/hello-design-patterns/concurrency/proactor">主动器模式</a></li></ul><h3 id="其他模式" tabindex="-1">其他模式 <a class="header-anchor" href="#其他模式" aria-label="Permalink to “其他模式”">​</a></h3><ul><li><a href="/hello-design-patterns/other/overview">其他模式导读</a></li><li><a href="/hello-design-patterns/other/mvc">MVC 模式</a></li><li><a href="/hello-design-patterns/other/mvvm">MVVM 模式</a></li><li><a href="/hello-design-patterns/other/orm">对象-关系映射（ORM）</a></li><li><a href="/hello-design-patterns/other/event-sourcing">事件溯源（Event Sourcing）</a></li></ul><h2 id="模式之间的关联" tabindex="-1">模式之间的关联 <a class="header-anchor" href="#模式之间的关联" aria-label="Permalink to “模式之间的关联”">​</a></h2><ul><li>单例模式与<a href="/hello-design-patterns/concurrency/double-checked-locking">双重检查锁定模式</a>常结合用于实现线程安全的延迟初始化。</li><li>代理模式的不同变体（<a href="/hello-design-patterns/structural/virtual-proxy">虚拟代理</a>、<a href="/hello-design-patterns/structural/protection-proxy">保护代理</a>、<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>、<a href="/hello-design-patterns/structural/dynamic-proxy">动态代理</a>）都围绕&quot;控制对对象的访问&quot;展开。</li><li><a href="/hello-design-patterns/behavioral/memento">备忘录模式</a>与<a href="/hello-design-patterns/behavioral/snapshot">快照模式</a>是同一类模式的不同叫法，通常用于撤销/重做。</li><li><a href="/hello-design-patterns/creational/factory-method">工厂方法</a>与<a href="/hello-design-patterns/creational/abstract-factory">抽象工厂</a>解决对象创建的解耦问题，<a href="/hello-design-patterns/creational/builder">建造者模式</a>则面向复杂对象的分步构建。</li><li><a href="/hello-design-patterns/concurrency/event-loop">事件循环</a>、<a href="/hello-design-patterns/concurrency/reactor">反应器</a>与<a href="/hello-design-patterns/concurrency/proactor">主动器</a>共同构成事件驱动 I/O 的核心模式族。</li></ul>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};